structure.mermaidSource:
flowchart TD
  start(["Início da Análise da Sentença"]) --> proc_via1["Passo 1: Testar a Via 1 (Palavra Isolada / Nível Lexical)"]
  proc_via1 --> dec_via1{"Há vocábulo polissêmico ou homônimo sem restrição clara no cotexto?"}
  dec_via1 -- "Sim" --> res_ambig_lexical["Ambiguidade Lexical / Imprecisão Vocabular"]
  dec_via1 -- "Não" --> proc_via2["Passo 2: Testar a Via 2 (Conectivos Específicos 'DE' e 'E')"]
  proc_via2 --> dec_prep_de{"Há preposição 'DE' com duplo papel: Agente (Adjunto) e Paciente (Complemento)?"}
  dec_prep_de -- "Sim" --> res_ambig_prep_de["Ambiguidade Sintática: Duplo Papel do 'DE' (Agente vs. Paciente)"]
  dec_prep_de -- "Não" --> proc_teste_coord["Avaliar escopo e modificadores da coordenação com 'E'"]
  proc_teste_coord --> dec_coord_e{"Há conectivo 'E' gerando escopo dúbio de coordenação?"}
  dec_coord_e -- "Sim" --> res_ambig_coord_e["Ambiguidade Estrutural por Escopo de Coordenação ('E')"]
  dec_coord_e -- "Não" --> proc_via3["Passo 3: Testar a Via 3 (Topologia, Posição dos Termos e Pronomes)"]
  proc_via3 --> dec_possessivo{"Há pronome possessivo de 3ª pessoa ('seu/sua') com múltiplos referentes?"}
  dec_possessivo -- "Sim" --> res_ambig_possessivo["Ambiguidade Pronominal: Referente Dúbio do Possessivo"]
  dec_possessivo -- "Não" --> proc_teste_adverbio["Avaliar posição sintática de adjuntos adverbiais"]
  proc_teste_adverbio --> dec_adverbio{"Há adjunto adverbial intercalado/flutuante entre dois verbos?"}
  dec_adverbio -- "Sim" --> res_ambig_adverbio["Ambiguidade Topológica: Adjunto Adverbial Flutuante"]
  dec_adverbio -- "Não" --> proc_teste_relativo["Avaliar antecedentes nominais imediatos de pronomes relativos"]
  proc_teste_relativo --> dec_relativo{"Há pronome relativo com duplo antecedente sintático cabível?"}
  dec_relativo -- "Sim" --> res_ambig_relativo["Ambiguidade Sintática: Duplo Antecedente do Pronome Relativo"]
  dec_relativo -- "Não" --> res_sem_ambiguidade["Enunciado Isento de Ambiguidade: Sentido Unívoco e Preciso"]

flowchart TD
  start["Início: Questão sem Destaque Gráfico"] --> proc_comando["Passo 1: Leitura do Comando (Busca Correta ou Incorreta?)"]
  proc_comando --> proc_varredura["Passo 2: Varredura Léxica ('Sentir o Cheiro')"]
  proc_varredura --> dec_termo_critico{"Vocábulo do repertório crítico localizado na opção?"}
  dec_termo_critico -- "Não" --> res_rastreio_global["Reavaliar Regência e Sintaxe Global da Alternativa"]
  dec_termo_critico -- "Sim" --> proc_ancoragem["Passo 3: Ancoragem Contextual dos Modificadores"]
  proc_ancoragem --> dec_confronto{"Passo 4: A grafia é compatível com o sentido exigido?"}
  dec_confronto -- "Grafia Incompatível (Erro)" --> dec_cmd_incompativel{"O comando busca a alternativa INCORRETA?"}
  dec_cmd_incompativel -- "Sim" --> res_marcar_erro["GABARITO: Marcar Alternativa Incorreta"]
  dec_cmd_incompativel -- "Não" --> res_eliminar_erro["ELIMINAR: Alternativa Incorreta"]
  dec_confronto -- "Grafia Compatível (Correta)" --> dec_cmd_compativel{"O comando busca a alternativa CORRETA?"}
  dec_cmd_compativel -- "Sim" --> res_marcar_acerto["GABARITO: Marcar Alternativa Correta"]
  dec_cmd_compativel -- "Não" --> res_eliminar_acerto["ELIMINAR: Alternativa Correta"]
